"""Playfield visual-only storybook. No commerce API or credential submission."""
from pathlib import Path
import json, html

ROOT=Path(__file__).resolve().parent.parent
ICONS=json.loads((ROOT/'source/icons.json').read_text())
def icon(name): return ICONS[name]
def link(label,dest,cls=''): return f'<a class="{cls}" href="{dest}.html">{label}</a>'
def button(label,dest,secondary=False): return link(label+icon('ArrowRight'),dest,'button secondary' if secondary else 'button')
def pic(name,alt,cls=''): return f'<img class="{cls}" src="../assets/{name}.png" alt="{alt}">'
def eyebrow(s): return f'<p class="eyebrow">{s}</p>'
def heading(kicker,title,copy=''):return f'<div class="section-title">{eyebrow(kicker)}<h1>{title}</h1>{f"<p>{copy}</p>" if copy else ""}</div>'

products=[
 {'id':'pattern-studio','name':'Pattern Studio','subtitle':'Wooden mosaic kit','age':'6–8 years','interest':'Art','contents':'12 tiles · 2 idea cards · 1 tray','price':1290,'option':'Garden · 12 tiles','image':'pattern-studio'},
 {'id':'paper-play','name':'Paper Play','subtitle':'Colour & folding paper','age':'6–8 years','interest':'Art','contents':'36 A5 sheets · 6 colours','price':490,'option':'Colour mix · A5','image':'paper-play'},
 {'id':'arch-paths','name':'Arch Paths','subtitle':'Wooden building arches','age':'3–5 years','interest':'Building','contents':'6 arches · largest 18 cm wide','price':990,'option':'Meadow · 6 pieces','image':'arch-paths'},
 {'id':'story-cards','name':'Make a Story','subtitle':'Printed pattern cards','age':None,'interest':'Art','contents':'Contents not supplied','price':290,'option':'One edition','image':None},
]
def money(n):return '₹'+f'{n:,}'
def card(p,missing=False):
 image=pic(p['image'],p['name']+' whole product') if p['image'] else '<div class="missing-media">'+icon('Package')+'<span>Product image<br>not supplied</span></div>'
 return f'<article class="product-card" data-age="{p["age"] or "unknown"}" data-interest="{p["interest"]}"><a class="card-image" href="04-product-main.html">{image}<span class="age-label">{p["age"] or "Age information not supplied"}</span></a><div class="card-copy"><span class="micro">{p["interest"]}</span><h3>{link(p["name"],"04-product-main")}</h3><p>{p["subtitle"]}</p><p class="card-fact">{p["contents"]}</p><div class="card-bottom"><strong>{money(p["price"])}</strong>{link('View kit '+icon('ArrowRight'),'04-product-main','text-link')}</div></div></article>'
def header():return f'''<div class="announcement">A little curiosity. A world of possibilities.</div><header class="site-header"><div class="wrap header-inner"><details class="mobile-menu"><summary aria-label="Open navigation">{icon('Menu')}</summary><nav>{link('Shop by age','03-collection')}{link('Interests','03-collection')}{link('Toys & puzzles','03-collection')}{link('Creative kits','03-collection')}{link('Product information','05-product-contents')}</nav></details>{link('<span class="brand-shapes">● ◒</span> playfield','01-home-top','wordmark')}<nav class="desktop-nav">{link('Shop by age','03-collection')}{link('Interests','03-collection')}{link('Creative kits','03-collection')}{link('Product information','05-product-contents')}</nav><div class="utilities">{link(icon('Search')+'<span>Search</span>','03-collection','utility')}{link(icon('UserRound')+'<span>Account</span>','12-profile','utility account-utility')}{link(icon('ShoppingBag')+'<b class="bag-count">2</b>','07-cart','utility')}</div></div></header>'''
def footer():return f'''<footer class="footer"><div class="wrap footer-grid"><div>{link('● ◒ playfield','01-home-top','wordmark')}<p>Thoughtful things for curious days.</p><p>For grown-ups choosing the next activity.</p></div><div><h3>Explore</h3>{link('Shop by age','03-collection')}{link('Art & making','03-collection')}{link('Toys & puzzles','03-collection')}</div><div><h3>Good to know</h3>{link('Product information','05-product-contents')}{link('Care & policy information','06-product-continuation')}{link('Order help','14-order-detail')}</div><div><h3>Your account</h3>{link('Sign in with LetBuyy','10-sign-in')}{link('Your orders','13-orders')}{link('Saved addresses','15-addresses')}</div></div><div class="wrap footer-bottom"><span>© 2026 Playfield · Fictional visual reference</span><span>India · INR ₹</span></div></footer>'''
def breadcrumb(s):return f'<div class="breadcrumb">{link("Home","01-home-top")} {icon("ChevronRight")} {s}</div>'
def strip():return f'<div class="product-strip wrap"><div><strong>Pattern Studio</strong><span>Garden · 12 tiles · {money(1290)}</span></div>{link("Back to selection "+icon("ArrowRight"),"04-product-main","text-link")}</div>'
def service():return f'<div class="service-grid wrap"><div>{icon("Package")}<div><strong>Know what is inside</strong><p>Contents before commitment.</p></div></div><div>{icon("Ruler")}<div><strong>A clearer sense of scale</strong><p>Measurements alongside the image.</p></div></div><div>{icon("CircleHelp")}<div><strong>Questions welcome</strong><p>Find policy and order help in one place.</p></div></div></div>'
def summary(checkout=True):
 return f'''<section class="summary"><h2>Order summary <span>2 items</span></h2><div class="summary-line">{pic('pattern-studio','Pattern Studio kit')}<div><strong>Pattern Studio</strong><p>Garden · 12 tiles</p><p>Qty 1</p></div><strong>₹1,290</strong></div><div class="summary-line">{pic('paper-play','Paper Play pack')}<div><strong>Paper Play</strong><p>Colour mix · A5</p><p>Qty 1</p></div><strong>₹490</strong></div><div class="totals"><div><span>Subtotal</span><strong>₹1,780</strong></div><div><span>Shipping</span><strong>{'₹80' if checkout else 'At checkout'}</strong></div><div><span>Taxes</span><span>Included in prices</span></div><div class="total"><span>{'Total' if checkout else 'Subtotal'} <small>INR</small></span><strong>{'₹1,860' if checkout else '₹1,780'}</strong></div></div><p class="micro">{'Sample confirmed quote · Bengaluru 560001' if checkout else 'Shipping and final amount confirmed at checkout.'}</p></section>'''
def field(label,value='',wide=False,placeholder='',error=''):
 ident=label.lower().replace(' ','-').replace('/','-')
 return f'<div class="field {"wide" if wide else ""}"><label for="{ident}">{label}</label><input id="{ident}" value="{value}" placeholder="{placeholder}" {"aria-invalid=true aria-describedby="+ident+"-error" if error else ""}>{f"<span id={ident}-error class=field-error>{error}</span>" if error else ""}</div>'
def checkout_top(step):return f'''<header class="checkout-header"><div class="wrap"><a href="07-cart.html" class="wordmark">playfield</a><span>{icon('LockKeyhole')} Checkout</span></div></header><div class="wrap checkout-steps"><span class="{'current' if step==1 else ''}">1 · Address</span>{icon('ChevronRight')}<span class="{'current' if step==2 else ''}">2 · Review & pay</span><span class="checkout-by">Powered by LetBuyy</span></div>'''
def checkout_footer():return '<footer class="checkout-footer wrap">Shared checkout · Shipping and returns · Privacy · Terms<br><span class="micro">Visual fixture. No payment or order is submitted.</span></footer>'
def account(content,active):
 nav=''.join(link(label,dest,'active' if label==active else '') for label,dest in [('Overview','12-profile'),('Orders','13-orders'),('Addresses','15-addresses')])
 return header()+f'<main class="wrap account-page"><div class="account-heading"><div>{eyebrow("YOUR PLAYFIELD ACCOUNT")}<h1>A place for your details.</h1></div>{link(icon("LogOut")+" Sign out","10-sign-in","text-link")}</div><div class="account-layout"><nav class="account-nav" aria-label="Account">{nav}</nav><div class="account-content">{content}</div></div></main>'+footer()
def identity(content, continuation=''):
 aside=continuation or '<div class="mini-pattern"><span>◒</span><span>◐</span><span>◓</span><span>●</span></div><h2>Your account.<br>More curious days.</h2><p>One LetBuyy buyer account.<br>Your Playfield orders and saved details.</p>'
 register=' identity-register' if continuation else ''
 return f'''<div class="identity-page{register}"><header class="identity-top"><img src="../assets/letbuyy-logo.svg" alt="LetBuyy"><span>Continuing to <strong>Playfield</strong></span></header><main class="identity-main"><section class="identity-card"><div class="destination">{icon('ShoppingBag')} Your destination: Playfield</div>{content}</section><aside class="identity-aside">{aside}</aside></main><footer class="identity-footer">Privacy · Terms · Help <span>Fictional visual reference · no credentials submitted</span></footer></div>'''


scenes=[]
def scene(id,title,desc,body,route):
 scenes.append({'id':id,'title':title,'description':desc,'source':f'source/{id}.html','intendedRoute':route})
 identity_style='<link rel="stylesheet" href="identity.css">' if id in ['10-sign-in','11-sign-up'] else ''
 out=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Playfield visual reference</title><link rel="stylesheet" href="styles.css">{identity_style}<script src="interactions.js" defer></script></head><body data-scene="{id}">{body}</body></html>'
 (ROOT/'source'/f'{id}.html').write_text(out)

scene('01-home-top','Home · choose a curious day','Announcement, navigable header, adult age/interest chooser, primary CTA, asymmetric activity bento.',header()+f'''<main><section class="wrap home-opening"><div class="home-intro">{eyebrow('FOR LITTLE IDEAS THAT GROW')}<h1>What will <br>we make today<span>?</span></h1><p>Toys, puzzles and hands-on activities.<br>Find a place to start, together.</p></div><form class="finder" action="03-collection.html"><div><span class="step-dot">1</span><label for="age">Choose an age</label><select id="age" name="age"><option>6–8 years</option><option>3–5 years</option><option>9–12 years</option></select></div><div><span class="step-dot">2</span><label for="interest">Follow an interest</label><select id="interest" name="interest"><option>Art</option><option>Building</option><option>Puzzles</option></select></div><button class="button" type="submit">Find an activity {icon('ArrowRight')}</button><p class="micro">Shopping for a young person? Age ranges come from the merchant.</p></form></section><section class="wrap activity-bento"><a class="bento-main" href="04-product-main.html">{pic('activity-hero','Adult hand arranging the twelve Pattern Studio tiles in their tray')}<div class="bento-caption"><div>{eyebrow('MAKE · ARRANGE · START AGAIN')}<h2>A little pattern.<br>A big possibility.</h2></div><span class="round-arrow">{icon('ArrowRight')}</span></div></a><div class="bento-side"><a class="bento-small coral" href="03-collection.html">{pic('paper-play','Coloured paper with illustrative folded paper examples')}<div><h3>Art & making</h3><span>For the next bright idea {icon('ArrowRight')}</span></div></a><a class="bento-small sage" href="03-collection.html">{pic('arch-paths','Six whole wooden arch blocks')}<div><h3>Build a little world</h3><span>Stack, balance, imagine {icon('ArrowRight')}</span></div></a></div></section><section class="wrap age-entry"><h2>Start with their age.</h2><div>{link('3–5 <span>years</span>'+icon('ArrowRight'),'03-collection','age-tile')}{link('6–8 <span>years</span>'+icon('ArrowRight'),'03-collection','age-tile selected')}{link('9–12 <span>years</span>'+icon('ArrowRight'),'03-collection','age-tile')}</div><p class="micro">These are merchant recommendations. Read each product’s information before choosing.</p></section></main>''','/ · opening')

scene('02-home-bottom','Home · more to explore','Age-labelled merchandising, included-content education, materials/care, merchant service information and footer.',header()+f'''<main><section class="wrap section"><div class="section-heading"><div>{eyebrow('FIND YOUR NEXT ACTIVITY')}<h1>Small things. Lots to explore.</h1></div>{link('Browse all activities '+icon('ArrowRight'),'03-collection','text-link')}</div><div class="age-group"><h2>For ages 6–8</h2><p>Art, colour and a fresh way to make.</p></div><div class="product-grid two">{card(products[0])}{card(products[1])}</div><div class="age-group"><h2>For ages 3–5</h2><p>One building set, many starting points.</p></div><div class="feature-row">{pic('arch-paths','Six separate Arch Paths blocks')}<div><span class="pill">3–5 years · Building</span><h2>Six arches.<br>Your own little landscape.</h2><p>See every piece, check the size, and read the supplied product information.</p>{button('Meet Arch Paths','04-product-main',True)}</div></div></section><section class="education"><div class="wrap education-grid"><div>{eyebrow('THE DETAILS MAKE A DIFFERENCE')}<h2>Know what comes<br>home with you.</h2><p>Look beyond the picture. Find included pieces, real measurements, materials and the merchant’s warnings together.</p>{link('Explore a kit’s contents '+icon('ArrowRight'),'05-product-contents','text-link')}</div><div class="contents-teaser"><div><strong>12</strong><span>wooden tiles</span></div><b>+</b><div><strong>2</strong><span>idea cards</span></div><b>+</b><div><strong>1</strong><span>storage tray</span></div></div></div></section>{service()}<section class="wrap care-banner"><h2>Play again. Put away. Start another day.</h2><p>Use the care instructions supplied with your product. Pattern Studio: wipe wood with a dry cloth and store the pieces in the tray.</p>{link('Materials & care '+icon('ArrowRight'),'06-product-continuation','text-link')}</section></main>'''+footer(),'/ · continuation')

scene('03-collection','Activities · age & interest','Composed age/interest filters, independent removable chips, factual cards, pagination and unknown-age disclosure.',header()+f'''<main class="wrap section collection-page">{breadcrumb('Activities')}{heading('FOLLOW THEIR CURIOSITY','A good day to make something.','Choose an age and interest. Take a closer look at every kit.')}<form class="collection-tools" id="filter-form"><div class="field"><label for="filter-age">Age recommendation</label><select id="filter-age" name="age"><option value="6–8 years">6–8 years</option><option value="">All ages / unknown</option><option value="3–5 years">3–5 years</option></select></div><div class="field"><label for="filter-interest">Interest</label><select id="filter-interest" name="interest"><option value="Art">Art</option><option value="">All interests</option><option value="Building">Building</option></select></div><div class="field"><label for="sort">Sort by</label><select id="sort"><option>Featured</option><option>Price: low to high</option></select></div><button class="button" type="submit">Apply {icon('Check')}</button></form><div class="filter-state"><div id="applied-chips"><button class="chip" data-clear="age" type="button">6–8 years {icon('X')}</button><button class="chip" data-clear="interest" type="button">Art {icon('X')}</button></div><button class="text-link" id="clear-all" type="button">Clear all</button></div><div class="age-group"><h2 id="result-title">Art for ages 6–8</h2><p id="result-count" aria-live="polite">2 activities · Showing 1–2</p></div><div class="product-grid two" id="results">{''.join(card(p) for p in products[:3])}</div><section class="empty-state" id="no-results" hidden><h2>No activities match both choices.</h2><p>Your choices are kept. Remove one filter to explore more.</p><button class="button secondary" type="button" data-clear="age">Remove age filter {icon('ArrowRight')}</button></section><nav class="pagination" aria-label="Pagination"><span>Page 1 of 1</span><button aria-label="Previous page" disabled>{icon('ArrowLeft')}</button><button class="selected" aria-current="page">1</button><button aria-label="Next page" disabled>{icon('ArrowRight')}</button></nav><section class="unknown-example"><div><h2>When age is not supplied</h2><p>These items are outside your age-filtered results. Ask the merchant for suitability information before choosing.</p></div>{card(products[3])}</section></main>'''+footer(),'/collections/activities?age=6-8&interest=art')

scene('04-product-main','Pattern Studio · selection','Whole-kit gallery, merchant-stated age and warning, real option labels, unavailable option, quantity and purchase.',header()+f'''<main class="wrap section pdp-main">{breadcrumb('Art & making '+icon('ChevronRight')+' Pattern Studio')}<div class="pdp-grid"><div class="gallery"><div class="gallery-main">{pic('pattern-studio','Whole Pattern Studio kit: twelve wooden tiles, two idea cards and one tray')}</div><div class="gallery-thumbs"><button class="selected" aria-label="View kit contents">{pic('pattern-studio','Kit contents')}</button><button aria-label="View activity context">{pic('activity-hero','Kit in use by an adult')}</button>{link(icon('Ruler')+'<span>Size & contents</span>','05-product-contents','diagram-thumb')}</div><p class="micro">Garden edition · All included pieces shown. Images are visual fixtures.</p></div><section class="purchase"><span class="pill">Art & patterns · Merchant age: 6–8 years</span><h1>Pattern Studio</h1><p class="product-subtitle">A wooden mosaic kit for little compositions.</p><div class="price">₹1,290 <span>Taxes included</span></div><p>Arrange, turn and begin again. Twelve patterned tiles, two idea cards and a tray to hold the next idea.</p><div class="facts-inline"><span>{icon('Shapes')} 15 pieces total</span><span>{icon('Ruler')} Tray 24 × 19 cm</span></div><fieldset><legend>Edition <span>Garden · 12 tiles</span></legend><div class="options"><button class="selected" type="button" aria-pressed="true">{icon('Check')} Garden</button><button type="button" aria-pressed="false">Ocean</button><button type="button" disabled>Sunrise <span>Unavailable</span></button></div></fieldset><p class="availability">{icon('Check')} Garden is available</p><div class="warning">{icon('CircleAlert')}<div><strong>Merchant-supplied warning</strong><p>Small parts. Not for children under 3 years. Adult supervision recommended.</p></div></div><div class="purchase-actions"><div class="quantity" aria-label="Quantity"><button aria-label="Decrease quantity" type="button">{icon('Minus')}</button><output>1</output><button aria-label="Increase quantity" type="button">{icon('Plus')}</button></div>{button('Add to cart · ₹1,290','07-cart')}</div><p class="micro">Shipping calculated at shared checkout.</p><div class="purchase-links">{link('What is included? '+icon('ArrowRight'),'05-product-contents','text-link')}{link('Care & policy information '+icon('ArrowRight'),'06-product-continuation','text-link')}</div></section></div></main>'''+service()+footer(),'/products/pattern-studio · selection')

scene('05-product-contents','Pattern Studio · contents & scale','Countable contents, dimensions with text equivalent, materials, sourced warning and absence states.',header()+strip()+f'''<main><section class="wrap section">{heading('OPEN THE BOX BEFORE YOU BUY','Every piece, accounted for.','Pattern Studio · Garden edition. Product facts supplied by the merchant for this fictional reference.')}<div class="contents-grid"><div class="contents-photo">{pic('pattern-studio','Twelve wooden tiles, two idea cards and one tray, separated for counting')}<span class="photo-label">The complete kit · 15 pieces</span></div><div class="contents-list"><div><b>12</b><section><h3>Patterned wooden tiles</h3><p>5 × 5 × 0.6 cm each</p></section></div><div><b>2</b><section><h3>Printed idea cards</h3><p>Two starting patterns. Make your own too.</p></section></div><div><b>1</b><section><h3>Birch storage tray</h3><p>24 × 19 × 1.5 cm outside dimensions</p></section></div><p class="micro">Nothing else needed for the pictured activity. No additional pieces or tools included.</p></div></div></section><section class="dimensions-section"><div class="wrap dimensions-grid"><div>{eyebrow('ROOM ON THE TABLE')}<h2>A clearer sense of scale.</h2><p>Tray: 19 cm wide × 24 cm long × 1.5 cm high. Each tile: 5 × 5 × 0.6 cm. Measurements are merchant-supplied; the diagram is schematic.</p><dl class="facts"><div><dt>Recommended age</dt><dd>6–8 years · merchant statement</dd></div><div><dt>Materials</dt><dd>Birch wood, painted finish; paper cards</dd></div><div><dt>Finish specification</dt><dd>Not supplied</dd></div></dl></div><div class="size-diagram" role="img" aria-label="Schematic tray: width 19 centimetres, length 24 centimetres, height 1.5 centimetres"><div class="measure horizontal">← 19 cm →</div><div class="diagram-row"><span class="measure vertical">24 cm</span><div class="tray-diagram">{''.join('<span></span>' for _ in range(12))}</div></div><p>Height 1.5 cm · Not to scale</p></div></div></section><section class="wrap warning-panel"><h2>Read the supplied product information.</h2><div class="warning">{icon('CircleAlert')}<div><strong>Small parts. Not for children under 3 years.</strong><p>Adult supervision recommended. Merchant source: product label, Garden edition. This visual fixture makes no certification claim.</p></div></div><p>Age is a merchant recommendation, not a guarantee of suitability. Contact the merchant if information you need is missing.</p>{button('Return to Garden selection','04-product-main',True)}</section></main>'''+footer(),'/products/pattern-studio · contents')

