scene('07-cart','Cart · selected activities','Preserved options, quantities/removal, server-total fixture, shipping explanation, checkout and retry state.',header()+f'''<main class="wrap section">{heading('READY FOR A CURIOUS DAY?','Your cart.','2 activities, chosen by you.')}<div class="cart-layout"><div>{cartlines}<div class="notice">{icon('RefreshCw')}<div><strong>If an update fails, your choices stay here.</strong><p>Retry the quantity change. Checkout rechecks current price and availability.</p></div></div>{link(icon('ArrowLeft')+' Keep exploring','03-collection','text-link')}</div><aside>{summary(False)}{button('Continue to shared checkout','08-checkout-address')}<p class="micro cart-helper">Final amount and shipping shown before you pay.</p></aside></div></main>'''+footer(),'/cart')

scene('08-checkout-address','Shared checkout · address','Canonical contact, address, shipping selection and full quote fixture; profile-independent guest path.',checkout_top(1)+f'''<main class="wrap checkout-layout"><section><div class="checkout-title"><h1>Where shall we send it?</h1><p>Contact and delivery details for this order.</p></div><div class="section-heading compact"><h2>Contact</h2>{link('Sign in with LetBuyy','10-sign-in','text-link')}</div>{field('Email','mira@example.test',True)}<p class="micro">We will use this for order updates.</p><h2 class="form-heading">Delivery address</h2><div class="form-grid">{field('First name','Mira')}{field('Last name','Demo')}{field('Address','14 Example Lane',True)}{field('Apartment / landmark','Demo House',True)}{field('City','Bengaluru')}{field('PIN code','560001')}{field('State','Karnataka')}{field('Country','India')}</div><h2 class="form-heading">Shipping method</h2><label class="radio-card"><input type="radio" name="shipping" checked><span><strong>Standard shipping</strong><small>Confirmed for this sample address. Delivery date not supplied.</small></span><strong>₹80</strong></label>{button('Continue to review','09-checkout-review')}{link('Return to cart','07-cart','text-link')}</section><aside>{summary()}</aside></main>'''+checkout_footer(),'/checkout/address · shared hosted origin')

scene('09-checkout-review','Shared checkout · review & pay','All lines and totals before commitment, contact/shipping confirmation, eligible-method fixture and recoverable failure.',checkout_top(2)+f'''<main class="wrap checkout-layout review"><section><div class="checkout-title"><h1>A last look, then pay.</h1><p>Check your activities and delivery details.</p></div><div class="review-address"><div><strong>Contact</strong><p>mira@example.test</p></div>{link('Change','08-checkout-address','text-link')}<div><strong>Deliver to</strong><p>Mira Demo · 14 Example Lane, Demo House<br>Bengaluru, Karnataka 560001 · India</p></div>{link('Change','08-checkout-address','text-link')}<div><strong>Shipping</strong><p>Standard shipping · ₹80</p></div></div><div class="review-inline-summary">{summary()}</div><h2 class="form-heading">Payment</h2><p class="micro">Methods depend on this order and merchant eligibility.</p><label class="radio-card selected"><input type="radio" name="pay" checked><span><strong>Pay online</strong><small>UPI, cards and other methods offered by the payment provider.</small></span>{icon('CreditCard')}</label><label class="radio-card"><input type="radio" name="pay"><span><strong>Cash on delivery</strong><small>Available for this fictional quote only.</small></span></label><div class="error-note" role="status">{icon('CircleAlert')}<div><strong>Payment could not start. No order was placed.</strong><p>Your choices are saved for this attempt. Retry after checking the order summary.</p></div></div><button class="button block prototype-action" type="button">Retry payment · ₹1,860 {icon('ArrowRight')}</button><p class="micro">Review the merchant terms before placing your order. The provider confirms payment; this visual reference submits nothing.</p>{link('Back to address','08-checkout-address','text-link')}</section><aside class="review-side-summary">{summary()}</aside></main>'''+checkout_footer(),'/checkout/review · shared hosted origin')

scene('10-sign-in','LetBuyy buyer sign-in · Playfield','Current canonical email/password entry with recoverable error, configured bot-check note and explicit Playfield destination.',identity(f'''<h1>Sign in</h1><p>Use your LetBuyy account to continue to Playfield.</p>{field('Email','mira@example.test',True)}<div class="field"><label for="password">Password</label><input id="password" type="password" placeholder="Enter your password" autocomplete="current-password"></div><div class="identity-error" role="status">{icon('CircleAlert')}<p>Invalid email or password. Try again.</p></div><button class="button block prototype-action" type="button">Sign in {icon('ArrowRight')}</button><div class="bot-check-note"><strong>Bot verification · when configured</strong><p>The configured challenge appears here when enabled. This visual reference has not completed a challenge.</p></div><div class="identity-links"><p>New to LetBuyy? {link('Create an account','11-sign-up','text-link')}</p><button class="text-link prototype-action" type="button">Forgot password?</button></div><div class="notice"><p>After sign-in, review the account and choose <strong>Continue to Playfield</strong>. Signing in does not automatically redirect you.</p></div>'''),'/buyer/authorize · sign-in screen · canonical identity origin')

scene('11-sign-up','LetBuyy create account · explicit Continue','Email/password creation (minimum eight characters), conditional bot verification and a labelled subsequent signed-in Continue state.',identity(f'''<span class="identity-step">1 · Create account</span><h1>Create your LetBuyy account</h1><p>One account for Playfield and every other LetBuyy store.</p>{field('Email','mira@example.test',True)}<div class="field"><label for="new-password">Password</label><input id="new-password" type="password" placeholder="Create a password" autocomplete="new-password" minlength="8"><p class="micro">At least 8 characters.</p></div><button class="button block prototype-action" type="button">Create account {icon('ArrowRight')}</button><div class="bot-check-note"><strong>Bot verification · when configured</strong><p>Complete the configured challenge when enabled. No challenge is simulated as passed.</p></div><p class="identity-legal">Buyer terms and privacy information are available through LetBuyy.</p><p class="identity-links">Already have an account? {link('Sign in','10-sign-in','text-link')}</p>''',f'''<section class="identity-continue" id="signed-in-state"><span class="identity-step">2 · After successful account creation</span><h2>Continue to Playfield</h2><p>You’re signed in to LetBuyy as <strong>mira@example.test</strong>.</p><p>Playfield will receive your email address.</p><button class="button block prototype-action" type="button">Continue to Playfield {icon('ArrowRight')}</button><button class="button secondary block prototype-action" type="button">Use a different account</button><p class="micro">Choose Continue to authorize the return to Playfield. This is the next state of the same identity flow.</p></section>'''),'/buyer/authorize?screen=register · creation + subsequent signed-in Continue state')

scene('12-profile','Account · overview & profile','Merchant account shell, fictional existing buyer identity, supported editing and navigation; verification state is independent of signup.',account(f'''<div class="section-heading"><div>{eyebrow('WELCOME BACK, MIRA')}<h2>Your next curious day starts here.</h2><p>Manage the details used for your Playfield orders.</p></div></div><div class="account-panels"><section class="panel"><div class="section-heading compact"><h2>Profile</h2><span class="pill">Email verified</span></div><div class="form-grid">{field('First name','Mira')}{field('Last name','Demo')}</div><dl class="facts"><div><dt>Account email</dt><dd>mira@example.test</dd></div></dl><button class="button prototype-action" type="button">Save profile {icon('Check')}</button><p class="micro">Changing your account email follows LetBuyy’s verification flow.</p></section><section class="panel soft"><span class="round-icon">{icon('Package')}</span><h2>Order PLF-1026</h2><p>Placed 22 October 2026<br>2 items · ₹1,860</p><span class="pill">Processing</span>{button('View order','14-order-detail',True)}</section></div><div class="account-shortcuts">{link(icon('MapPin')+'<div><h3>Saved addresses</h3><p>1 address · Example home is default</p></div>'+icon('ArrowRight'),'15-addresses')}{link(icon('Package')+'<div><h3>Your orders</h3><p>Find details and order help</p></div>'+icon('ArrowRight'),'13-orders')}</div>''','Overview'),'/account')

scene('13-orders','Account · order history','Owned-order list, identifiable date/status/total, exact products and direct detail link; useful empty/error recovery.',account(f'''<div class="section-heading"><div>{eyebrow('YOUR PURCHASES')}<h2>Good things to look back on.</h2><p>Orders linked to this buyer account at Playfield.</p></div></div><article class="order-card"><div class="order-card-top"><div><h3>PLF-1026</h3><p>Placed 22 October 2026</p></div><span class="pill">Processing</span><strong>₹1,860</strong></div><div class="order-products"><div>{pic('pattern-studio','Pattern Studio')}<span>Pattern Studio<br><small>Garden · 12 tiles · Qty 1</small></span></div><div>{pic('paper-play','Paper Play')}<span>Paper Play<br><small>Colour mix · A5 · Qty 1</small></span></div></div><div class="order-card-bottom"><span>2 items · Payment received</span>{button('View order details','14-order-detail',True)}</div></article><nav class="pagination" aria-label="Orders pages"><span>1 order · Page 1 of 1</span></nav><div class="notice">{icon('CircleHelp')}<div><strong>Missing an order?</strong><p>Check the email used at checkout. If loading fails, keep this account context and retry before showing an empty history.</p>{link('Order help','14-order-detail','text-link')}</div></div>{link(icon('ArrowLeft')+' Back to activities','03-collection','text-link')}''','Orders'),'/account/orders')

scene('14-order-detail','Account · owned order detail','Same variants/amounts as cart, status/payment/fulfillment separation, fictional address, totals and support route.',account(f'''{link(icon('ArrowLeft')+' All orders','13-orders','text-link')}<div class="section-heading order-heading"><div>{eyebrow('PLACED 22 OCTOBER 2026')}<h2>Order PLF-1026</h2><p>Your two activities are being prepared.</p></div><span class="pill">Processing</span></div><div class="order-detail-layout"><section><div class="timeline"><div class="done">{icon('CheckCircle2')}<span>Order received</span></div><div class="current">{icon('Package')}<span>Processing</span></div><div>{icon('Truck')}<span>Not dispatched</span></div></div><div class="order-items">{cartlines.replace('line-controls','line-controls readonly').replace('<div class="line-controls readonly">','<p class="micro">Quantity 1</p><div class="line-controls readonly">')}</div><div class="notice">{icon('CircleHelp')}<div><strong>Need help with this order?</strong><p>Contact the merchant quoting PLF-1026. Cancellation and return options depend on current order state and merchant policy.</p><a class="text-link" href="mailto:help@example.test">Contact order support {icon('ArrowRight')}</a></div></div></section><aside>{summary()}<section class="panel delivery-card"><h3>Delivery details</h3><p>Mira Demo<br>14 Example Lane, Demo House<br>Bengaluru, Karnataka 560001 · India</p><h3>Payment</h3><p>Received · Online payment</p><h3>Shipping</h3><p>Standard · ₹80<br>Tracking not yet available.</p></section></aside></div>''','Orders'),'/account/orders/PLF-1026 · owned buyer only')

scene('15-addresses','Account · saved address & validation','Default address, representative edit with PIN validation, cancel/save and no deletion of existing record on failure.',account(f'''<div class="section-heading"><div>{eyebrow('READY FOR NEXT TIME')}<h2>Your places.</h2><p>Saved addresses for your Playfield orders.</p></div><a class="button secondary" href="#address-form">Add address {icon('Plus')}</a></div><div class="addresses-layout"><section class="address-card"><span class="pill">Default</span><h3>Example home</h3><p>Mira Demo<br>14 Example Lane, Demo House<br>Bengaluru, Karnataka 560001<br>India</p><div>{link(icon('Pencil')+' Edit','#address-form','text-link') if False else '<a class="text-link" href="#address-form">'+icon('Pencil')+' Edit</a>'}<button class="text-link prototype-action" type="button">Remove</button></div></section><section class="panel" id="address-form"><div class="section-heading compact"><h2>Edit Example home</h2><span class="micro">Existing default stays saved</span></div><div class="error-note">{icon('CircleAlert')}<p>Check the PIN code. Your other details are kept.</p></div><form class="form-grid" onsubmit="return false">{field('First name','Mira')}{field('Last name','Demo')}{field('Address','14 Example Lane',True)}{field('Apartment / landmark','Demo House',True)}{field('City','Bengaluru')}{field('PIN code','5600',error='Enter a 6-digit Indian PIN code.')}{field('State','Karnataka')}{field('Country','India')}<label class="checkbox-row wide"><input type="checkbox" checked><span>Use as my default address</span></label><div class="form-actions wide"><button class="button prototype-action" type="button">Save address {icon('Check')}</button>{link('Cancel','15-addresses','text-link')}</div></form></section></div>''','Addresses'),'/account/addresses · list + edit state')

(ROOT/'scenes.json').write_text(json.dumps(scenes,indent=2)+'\n')
(ROOT/'source/fixtures.json').write_text(json.dumps({'fictional':True,'products':products,'cart':{'items':[{'product':'pattern-studio','option':'Garden · 12 tiles','quantity':1,'price':1290},{'product':'paper-play','option':'Colour mix · A5','quantity':1,'price':490}],'subtotal':1780,'shipping':80,'total':1860,'tax':'included in prices; fixture only'},'buyer':{'name':'Mira Demo','email':'mira@example.test'},'order':{'id':'PLF-1026','date':'2026-10-22','status':'processing','payment':'received','fulfillment':'not dispatched'}},indent=2)+'\n')
print(f'Built {len(scenes)} Playfield scenes')
